#include <iostream>
#include <utility>

void bubbleSort(double arr[], int size) {
    bool changed = true;
    for (int pass = 1; pass < size && changed; ++pass) {
        changed = false;
        for (int j = 0; j < size - pass; ++j) {
            if (arr[j] > arr[j + 1]) {
                std::swap(arr[j], arr[j + 1]);
                changed = true;
            }
        }
    }
}

int main() {
    const int SIZE = 10;
    double data[SIZE];
    for (int i = 0; i < SIZE; ++i) {
        if (!(std::cin >> data[i])) return 0;
    }

    bubbleSort(data, SIZE);

    for (int i = 0; i < SIZE; ++i) {
        std::cout << data[i] << (i + 1 == SIZE ? "" : " ");
    }
    std::cout << "\n";
    return 0;
}

#include <iostream>

bool strictlyEqual(const int list1[], const int list2[], int size) {
    for (int i = 0; i < size; ++i) {
        if (list1[i] != list2[i]) return false;
    }
    return true;
}

bool isConsecutiveFour(const int values[], int size) {
    if (size < 4) return false;
    int count = 1;
    for (int i = 1; i < size; ++i) {
        if (values[i] == values[i - 1]) {
            ++count;
            if (count == 4) return true;
        } else {
            count = 1;
        }
    }
    return false;
}

int main() {
    int a1[] = {3, 4, 5, 5, 5, 5, 4, 5};
    int a2[] = {3, 4, 5, 5, 5, 5, 4, 5};
    int a3[] = {3, 4, 5, 5, 6, 5, 5, 4};

    std::cout << (strictlyEqual(a1, a2, 8) ? "Equal" : "Not Equal") << "\n";
    std::cout << (isConsecutiveFour(a1, 8) ? "Has consecutive four" : "No consecutive four") << "\n";
    std::cout << (isConsecutiveFour(a3, 8) ? "Has consecutive four" : "No consecutive four") << "\n";

    return 0;
}

#include <iostream>

void merge(const int list1[], int size1, const int list2[], int size2, int list3[]) {
    int i = 0, j = 0, k = 0;
    while (i < size1 && j < size2) {
        if (list1[i] <= list2[j]) {
            list3[k++] = list1[i++];
        } else {
            list3[k++] = list2[j++];
        }
    }
    while (i < size1) {
        list3[k++] = list1[i++];
    }
    while (j < size2) {
        list3[k++] = list2[j++];
    }
}

int main() {
    const int list1[] = {1, 5, 16, 61, 111};
    const int list2[] = {2, 4, 5, 6};
    const int size1 = sizeof(list1) / sizeof(list1[0]);
    const int size2 = sizeof(list2) / sizeof(list2[0]);
    int list3[size1 + size2];

    merge(list1, size1, list2, size2, list3);

    std::cout << "The merged list is";
    for (int idx = 0; idx < size1 + size2; ++idx) {
        std::cout << " " << list3[idx];
    }
    std::cout << "\n";
    return 0;
}
